use super::*;
impl Materials {
 fn clone_assets(&self,bundle:&Bundle,created:&mut Vec<PathBuf>)->Result<Bundle,String>{
  let mut copy=bundle.clone();
  for item in &mut copy.items {let source=self.asset(&item.id);item.id=id();if item.kind!="text"{let target=self.asset(&item.id);let mut input=fs::File::open(source).map_err(err)?;let mut output=fs::OpenOptions::new().write(true).create_new(true).open(&target).map_err(err)?;created.push(target);std::io::copy(&mut input,&mut output).map_err(err)?;output.sync_all().map_err(err)?;}}
  Ok(copy)
 }
 pub(crate) fn initialize_workspace(&mut self){if self.load_error.is_none(){if let Err(error)=self.workspace_action("get",None,None){self.load_error=Some(error);}}}
 fn workspace_view(&self,packs:&TaskPacks,name:Option<String>)->serde_json::Value{serde_json::json!({"active":"workspace","previous_active":packs.active,"canUndo":packs.undo.is_some(),"savedName":name,"packs":packs.packs.iter().filter(|p|!p.bundle.items.is_empty()).map(|p|serde_json::json!({"id":p.id,"name":p.name,"count":p.bundle.items.len(),"created_ms":p.created_ms})).collect::<Vec<_>>()})}
 pub(crate) fn workspace_action(&self,action:&str,target:Option<&str>,name:Option<&str>)->Result<serde_json::Value,String>{
  self.ready()?;let _operation=self.operation.lock().map_err(err)?;if action!="get"&&self.busy.load(std::sync::atomic::Ordering::SeqCst){return Err("Finish capture before changing materials".into());}
  let mut bundle=self.bundle.lock().map_err(err)?;let mut packs=self.packs.lock().map_err(err)?;let mut next=packs.clone();let mut created=Vec::new();let mut saved=None;let mut changed=false;
  let result=(||->Result<(),String>{
   if next.workspace.is_none(){
    let current=next.packs.iter().position(|p|p.id==next.active).ok_or("Task pack missing")?;
    next.packs[current].bundle=self.clone_assets(&bundle,&mut created)?;next.workspace=Some(bundle.clone());next.version=2;
    let file=self.root.join("session.json");let backup=self.root.join("session.pre-workspace.json");if file.exists()&&!backup.exists(){let mut input=fs::File::open(file).map_err(err)?;let mut out=fs::OpenOptions::new().write(true).create_new(true).open(backup).map_err(err)?;std::io::copy(&mut input,&mut out).map_err(err)?;out.sync_all().map_err(err)?;}changed=true;
   }
   match action {
    "get"=>{},
    "save"=>{
     if bundle.items.is_empty(){return Err("No materials to save".into());}
     let stamp=name.ok_or("Missing material pack timestamp")?;
     if stamp.len()!=15||stamp.as_bytes()[8]!=b'-'||!stamp.bytes().enumerate().all(|(i,c)|i==8||c.is_ascii_digit()){return Err("Invalid material pack timestamp".into());}
     let base=format!("素材包 {stamp}");let mut title=base.clone();let mut suffix=2u64;
     while next.packs.iter().any(|p|p.name==title){title=format!("{base}-{suffix:02}");suffix=suffix.checked_add(1).ok_or("Pack sequence exhausted")?;}
     let copy=self.clone_assets(&bundle,&mut created)?;next.packs.push(TaskPack{id:id(),name:title.clone(),bundle:copy,created_ms:SystemTime::now().duration_since(UNIX_EPOCH).map_err(err)?.as_millis() as u64});saved=Some(title);changed=true;
    },
    "add"|"replace"=>{let source=next.packs.iter().find(|p|Some(p.id.as_str())==target).ok_or("Material pack not found")?.bundle.clone();let copy=self.clone_assets(&source,&mut created)?;let mut result=if action=="add"{bundle.clone()}else{Bundle::default()};result.items.extend(copy.items);validate_bundle(result.clone())?;next.workspace=Some(result);next.undo=None;changed=true;},
    "delete"=>{let index=next.packs.iter().position(|p|Some(p.id.as_str())==target).ok_or("Material pack not found")?;next.packs.remove(index);if next.packs.is_empty(){next.packs.push(TaskPack{id:id(),name:"My task".into(),bundle:Bundle::default(),created_ms:0});}if !next.packs.iter().any(|p|p.id==next.active){next.active=next.packs[0].id.clone();}changed=true;},
    "clear"=>{if !bundle.items.is_empty(){next.undo=Some(bundle.clone());next.workspace=Some(Bundle::default());changed=true;}},
    "undo"=>{let mut restored=next.undo.clone().ok_or("Nothing to restore")?;restored.items.extend(bundle.items.clone());validate_bundle(restored.clone())?;next.workspace=Some(restored);next.undo=None;changed=true;},
    "rename"=>{let title=name.unwrap_or("").trim();if title.is_empty()||title.chars().count()>80||title.chars().any(char::is_control){return Err("Enter a material pack name (1–80 characters)".into());}if next.packs.iter().any(|p|Some(p.id.as_str())!=target&&p.name.to_lowercase()==title.to_lowercase()){return Err("Material pack name already exists".into());}next.packs.iter_mut().find(|p|Some(p.id.as_str())==target).ok_or("Material pack not found")?.name=title.into();changed=true;},
    _=>return Err("Unknown workspace action".into())
   }
   if changed{self.write_packs(&next)?;}Ok(())
  })();
  if let Err(error)=result{for file in created{let _=fs::remove_file(file);}return Err(error);}
  if changed{*bundle=next.bundle();*packs=next;}Ok(self.workspace_view(&packs,saved))
 }
}
#[tauri::command]
pub async fn materials_workspace(w:tauri::WebviewWindow,app:tauri::AppHandle,action:String,target:Option<String>,name:Option<String>)->Result<serde_json::Value,String>{
 manager(&w)?;let changed=action!="get";let handle=app.clone();let result=tauri::async_runtime::spawn_blocking(move||{if action!="get"&&handle.state::<crate::recording::Recorder>().active(){return Err("Finish recording before changing materials".into());}handle.state::<Materials>().workspace_action(&action,target.as_deref(),name.as_deref())}).await.map_err(err)??;
 if changed{let _=app.emit_to("materials-quick","materials-updated",());}Ok(result)
}

#[cfg(test)]mod tests{
 use super::*;
 #[test]fn deleting_all_saved_packs_preserves_workspace_undo_and_counter(){let mut state=seed();state.initialize_workspace();state.workspace_action("save",None,Some("20261101-153045")).unwrap();state.workspace_action("clear",None,None).unwrap();let undo=serde_json::to_vec(&state.packs.lock().unwrap().undo).unwrap();let ids:Vec<_>=state.packs.lock().unwrap().packs.iter().map(|p|p.id.clone()).collect();for id in ids{state.workspace_action("delete",Some(&id),None).unwrap();}assert!(state.workspace_action("get",None,None).unwrap()["packs"].as_array().unwrap().is_empty());assert_eq!(serde_json::to_vec(&state.packs.lock().unwrap().undo).unwrap(),undo);state.workspace_action("undo",None,None).unwrap();assert_eq!(state.bundle.lock().unwrap().items.len(),2);let mut restarted=Materials::new(state.root.clone()).unwrap();restarted.initialize_workspace();assert_eq!(restarted.workspace_action("save",None,Some("20261101-153045")).unwrap()["savedName"],"素材包 20261101-153045");let before=fs::read(state.root.join("session.json")).unwrap();assert!(restarted.workspace_action("delete",Some("missing"),None).is_err());assert_eq!(fs::read(state.root.join("session.json")).unwrap(),before);fs::remove_dir_all(state.root).unwrap();}
 fn seed()->Materials{let root=std::env::temp_dir().join(format!("workspace-{}",id()));let state=Materials::new(root).unwrap();state.append(Item{id:"abc".into(),name:"shot.png".into(),kind:"image".into(),text:String::new(),size:3},Some(b"PNG")).unwrap();state.append(Item{id:"a1".into(),name:"Text".into(),kind:"text".into(),text:"original".into(),size:0},None).unwrap();state}
 #[test]fn migration_backups_ids_and_serial_snapshots_are_independent(){let mut state=seed();let before=fs::read(state.root.join("session.json")).unwrap();state.initialize_workspace();assert!(state.load_error.is_none());assert_eq!(fs::read(state.root.join("session.pre-workspace.json")).unwrap(),before);assert_eq!(state.bundle.lock().unwrap().items[0].id,"abc");let old=state.packs.lock().unwrap().packs[0].bundle.items[0].id.clone();assert_ne!(old,"abc");assert_eq!(fs::read(state.asset(&old)).unwrap(),b"PNG");let saved=state.workspace_action("save",None,Some("20261101-153045")).unwrap();assert_eq!(saved["savedName"],"素材包 20261101-153045");let saved_id=state.packs.lock().unwrap().packs.last().unwrap().id.clone();state.workspace_action("rename",Some(&saved_id),Some("素材包 20261101-153045")).unwrap();let saved=state.workspace_action("save",None,Some("20261101-153045")).unwrap();assert_eq!(saved["savedName"],"素材包 20261101-153045-02");assert_eq!(state.bundle.lock().unwrap().items[0].id,"abc");let restarted=Materials::new(state.root.clone()).unwrap();assert!(restarted.load_error.is_none());assert_eq!(restarted.workspace_action("save",None,Some("20261101-153045")).unwrap()["savedName"],"素材包 20261101-153045-03");fs::remove_dir_all(state.root).unwrap();}
 #[test]fn clear_undo_and_load_never_mutate_saved_packs(){let mut state=seed();state.initialize_workspace();state.workspace_action("save",None,Some("20261101-153045")).unwrap();let target=state.packs.lock().unwrap().packs.last().unwrap().id.clone();let saved=serde_json::to_vec(&state.packs.lock().unwrap().packs).unwrap();state.workspace_action("clear",None,None).unwrap();assert!(state.bundle.lock().unwrap().items.is_empty());let restarted=Materials::new(state.root.clone()).unwrap();assert!(restarted.packs.lock().unwrap().undo.is_some());restarted.append(Item{id:"a2".into(),name:"New".into(),kind:"text".into(),text:"keep new".into(),size:0},None).unwrap();restarted.workspace_action("undo",None,None).unwrap();assert_eq!(restarted.bundle.lock().unwrap().items.len(),3);assert!(restarted.workspace_action("undo",None,None).is_err());assert_eq!(serde_json::to_vec(&restarted.packs.lock().unwrap().packs).unwrap(),saved);restarted.workspace_action("add",Some(&target),None).unwrap();assert_eq!(restarted.bundle.lock().unwrap().items.len(),5);restarted.workspace_action("replace",Some(&target),None).unwrap();assert_eq!(restarted.bundle.lock().unwrap().items.len(),2);let image_id=restarted.bundle.lock().unwrap().items[0].id.clone();fs::write(restarted.asset(&image_id),b"NEW").unwrap();let saved_image=restarted.packs.lock().unwrap().packs.last().unwrap().bundle.items[0].id.clone();assert_eq!(fs::read(restarted.asset(&saved_image)).unwrap(),b"PNG");assert_eq!(serde_json::to_vec(&restarted.packs.lock().unwrap().packs).unwrap(),saved);fs::remove_dir_all(state.root).unwrap();}
 #[test]fn failed_save_and_limits_rollback_copies_counter_and_session(){let mut state=seed();state.initialize_workspace();let before=fs::read(state.root.join("session.json")).unwrap();let count=fs::read_dir(state.root.join("files")).unwrap().count();fs::create_dir(state.root.join("session.json.tmp")).unwrap();assert!(state.workspace_action("save",None,Some("20261101-153045")).is_err());assert_eq!(fs::read(state.root.join("session.json")).unwrap(),before);assert_eq!(fs::read_dir(state.root.join("files")).unwrap().count(),count);fs::remove_dir(state.root.join("session.json.tmp")).unwrap();assert_eq!(state.workspace_action("save",None,Some("20261101-153045")).unwrap()["savedName"],"素材包 20261101-153045");state.busy.store(true,std::sync::atomic::Ordering::SeqCst);assert!(state.workspace_action("clear",None,None).is_err());state.busy.store(false,std::sync::atomic::Ordering::SeqCst);assert!(state.workspace_action("replace",Some("missing"),None).is_err());let target=state.packs.lock().unwrap().packs.last().unwrap().id.clone();assert!(state.workspace_action("rename",Some(&target),Some(" ")).is_err());for n in 0..98{state.append(Item{id:format!("b{n:x}"),name:"Text".into(),kind:"text".into(),text:String::new(),size:0},None).unwrap();}let count=fs::read_dir(state.root.join("files")).unwrap().count();assert!(state.workspace_action("add",Some(&target),None).is_err());assert_eq!(state.bundle.lock().unwrap().items.len(),100);assert_eq!(fs::read_dir(state.root.join("files")).unwrap().count(),count);fs::remove_dir_all(state.root).unwrap();}
}
